UPDATE stock
SET quantity  = quantity - #{qty},
    updated_at = CURRENT_TIMESTAMP
WHERE warehouse_id = #{warehouseId}
  AND item_id = #{itemId}
  AND batch_id = #{batchId}
  AND location_id = #{locationId}
  AND quantity >= #{qty}
  AND quantity - pre_allocated_qty >= #{qty}

mapper.select:
UPDATE stock
SET quantity  = quantity - #{qty},
    updated_at = CURRENT_TIMESTAMP
WHERE warehouse_id = #{warehouseId}
  AND item_id = #{itemId}
  AND batch_id = #{batchId}
  AND location_id = #{locationId}
  AND quantity >= #{qty}
  AND quantity - pre_allocated_qty >= #{qty}
RETURNING quantity

mapper.update:
UPDATE stock
SET quantity  = quantity + #{qty},
    updated_at = CURRENT_TIMESTAMP
WHERE warehouse_id = #{warehouseId}
  AND item_id = #{itemId}
  AND batch_id = #{batchId}
  AND location_id = #{locationId}

UPDATE stock
SET pre_allocated_qty = pre_allocated_qty + #{qty},
    updated_at = CURRENT_TIMESTAMP
WHERE id = #{stockId}
  AND quantity - pre_allocated_qty >= #{qty}

UPDATE stock
SET pre_allocated_qty = pre_allocated_qty - #{qty},
    updated_at = CURRENT_TIMESTAMP
WHERE id = #{stockId}
  AND pre_allocated_qty >= #{qty}

UPDATE stock
SET quantity        = quantity - #{qty},
    pre_allocated_qty = pre_allocated_qty - #{qty},
    updated_at = CURRENT_TIMESTAMP
WHERE id = #{stockId}
  AND pre_allocated_qty >= #{qty}

